var Roblox=Roblox||{};Roblox.Lang=Roblox.Lang||{};Roblox.Lang['Feature.VerificationUpsell']={"Action.AddEmailAddress":"Masukkan Alamat Email","Action.AddPhone":"Tambahkan Nomor Ponsel","Action.AddPhoneNumber":"Tambahkan Nomor Ponsel","Action.AddPhoneVoice":"Tambahkan Ponsel untuk Chat Suara","Action.ChangeEmail":"Ubah Email","Action.ChangeNumber":"Ganti Nomor","Action.ChangePhoneNumber":"Ganti Nomor Telepon","Action.CodeResent":"Kode Terkirim","Action.Continue":"Lanjutkan","Action.Dialog.EditPhonePrimary":"Edit Nomor Ponsel","Action.Dialog.EditPhoneSecondary":"Hapus Nomor Ponsel","Action.Dialog.RemovePhonePrimary":"Hapus","Action.Dialog.RemovePhoneSecondary":"Batalkan","Action.Done":"Selesai","Action.Edit":"Edit","Action.EmailMyParent":"Kirim Email ke Orang Tua Saya","Action.EnableVoice":"Aktifkan Chat Suara","Action.FinishSetup":"Selesaikan Pengaturan","Action.GenericSkip":"Lewati","Action.LearnMore":"Pelajari Selengkapnya.","Action.Logout":"Tetap log out","Action.LogOutText":"Log Out","Action.LogoutWithRisk":"Terima Risiko Kehilangan Akun lalu Log Out","Action.Ok":"Oke","Action.PrivacyPolicy":"Kebijakan Privasi","Action.ResendCode":"Kirim Ulang Kode","Action.ResendConfirmationEmail":"Kirim ulang email","Action.SendConfirmationEmail":"Kirim Email Konfirmasi","Action.Sent":"Terkirim","Action.SetPassword":"Atur Password","Action.Support":"Bantuan","Action.UseEmail":"Gunakan email saja","Action.UserEmail":"Gunakan Email Saja","Action.Verify":"Verifikasi","Description.AddEmailTextOver13":"Untuk melanjutkan pembelian, masukkan alamat email kamu.","Description.AddEmailTextStrongMessaging":"Selesaikan pengaturan akun dengan memasukkan email untuk pemulihan akun. Dengan melewati langkah ini, kamu menerima bahwa kamu dapat kehilangan akses ke progres game, item, dan Robux.","Description.AddEmailTextUnder13":"Untuk melanjutkan pembelian, minta orang tuamu untuk memasukkan alamat email mereka.","Description.AddPhoneBodyVoice":"Kamu akan menerima kode verifikasi sekali pakai melalui WhatsApp atau SMS. Biaya SMS dan data mungkin berlaku.","Description.CanNowJoinVoice":"Sekarang kamu dapat bergabung ke pengalaman virtual yang mengaktifkan Chat Suara.","Description.CanNowTalk":"Sekarang kamu dapat berbicara dengan pengguna lain di Roblox secara natural seperti di dunia nyata.","Description.CanUsePhoneForRecovery":"Sekarang kamu dapat menggunakan nomor ponselmu untuk memulihkan akun di kemudian hari.","Description.Dialog.EditPhoneWarning":"Nomor ponsel tidak akan berubah sampai nomor ponsel yang baru terverifikasi.","Description.Dialog.RemovePhoneWarning":"Kamu yakin ingin menghapus nomor ponsel yang berakhir dengan {phoneLast4}?","Description.EnterPassword":"Masukkan password kamu.","Description.FacebookSetPasswordUpsellText":"Log in dengan akun Facebook sudah tidak lagi didukung lagi. Buat password agar akunmu tidak terkunci.","Description.IDVerificationAddEmailText":"Sebelum memverifikasi usia, masukkan alamat email kamu. Email ini akan menjadi metode pemulihan akun kalau kamu kehilangan akses ke akunmu.","Description.LogoutAddEmailTextOver13":"Sebelum log out, masukkan alamat email kamu agar akunmu tidak terkunci.","Description.LogoutAddEmailTextUnder13":"Sebelum log out, masukkan alamat email orang tuamu agar akunmu tidak terkunci.","Description.PhoneDiscoverabilityPrivacy":"Saat menggunakan Roblox, pengguna dengan nomor ponselmu akan dapat melihat namamu sesuai dengan yang tersimpan di perangkat mereka.\n\nUbah ini kapan saja di pengaturan privasi akunmu.","Description.PhoneForRecovery":"Sekarang kamu dapat menggunakan nomor ponselmu untuk memulihkan akun di kemudian hari.","Description.PhoneNumberNeverPublic":"Nomor ponselmu tidak akan pernah ditampilkan secara publik.","Description.PleaseEnterEmail":"Masukkan alamat email di akunmu.","Description.PleaseEnterEmailUnder13":"Masukkan alamat email orang tua kamu ke akun kamu.","Description.ShortCodeLegalDisclaimer":"Dengan mengklik \"Lanjutkan\", kamu memberikan nomor ponselmu dan menyetujui {linkTagWithSmsTos}Ketentuan Penggunaan SMS{linkTagEnd} dan {linkTagWithPrivacyPolicy}Kebijakan Privasi{linkTagEnd} kami. Kami akan mengirimi kamu kode verifikasi sekali pakai. Biaya SMS dan data mungkin berlaku. Balas \"HELP\" untuk bantuan.","Description.TurnOnVoiceChat":"Aktifkan Chat Suara di Pengaturan > Privasi > Input Mikrofon dan Kamera.","Description.VerificationCodeSmsFeesMayApply":"Kamu akan menerima kode verifikasi sekali pakai melalui WhatsApp atau SMS. Biaya SMS dan data mungkin berlaku.","Description.VerifyEmailBody":"Klik tautan di email konfirmasi yang kami kirim ke {emailAddress}.","Description.VoiceLegalConsent":"Saya memberikan izin kepada Roblox untuk mengumpulkan, menggunakan, dan menyimpan rekaman suara saya untuk mengaktifkan layanan suara dan untuk tujuan moderasi, keamanan, serta peningkatan layanan dan fitur Roblox.","Description.VoiceLegalDisclaimer":"Dengan memilih \"Aktifkan Chat Suara\", saya memberikan izin kepada Roblox untuk mengumpulkan, menggunakan, dan menyimpan rekaman suara saya untuk mengaktifkan layanan suara dan untuk tujuan moderasi, keamanan, serta peningkatan layanan dan fitur Roblox.","Description.WantToBeRecommendedViaPhone":"Akunmu ingin direkomendasikan ke pengguna Roblox yang memiliki nomor ponselmu? ","Header.LetFriendsFindYou":"Izinkan temanmu menemukan kamu","Header.PhoneIsVerified":"Nomor ponselmu terverifikasi","Heading.AddEmail":"Pertama, Verifikasikan Akunmu","Heading.CompleteSetupOnLogout":"Selesaikan Pengaturan Akun Sebelum Log Out","Heading.ConfirmPhone":"Konfirmasikan Nomor Ponsel","Heading.Dialog.RemovePhone":"Hapus Nomor Ponsel","Heading.DontGetLockedOut":"Jangan sampai Akun Kamu Terkunci","Heading.FinishAccountSetup":"Selesaikan Pengaturan Akun","Heading.ImproveAccountSecurity":"Tingkatkan Keamanan Akun","Heading.KeepAccountSecure":"Menjaga Akun Kamu tetap Aman","Heading.LetFriendsFindYou":"Izinkan Temanmu Menemukan Kamu","Heading.PhoneIsVerified":"Nomor Ponselmu Terverifikasi","Heading.PleaseAddEmail":"Tambahkan Alamat Email","Heading.VerificationCode":"Kode Verifikasi","Heading.VerificationRequired":"Verifikasi Diperlukan","Heading.VerifyEmail":"Periksa Email Kamu","Heading.VerifyOnLogout":"Jangan Sampai Akunmu Terkunci!","Heading.VerifySuccess":"Berhasil Diverifikasi","Heading.VerifyYourPhone":"Verifikasi Nomor Telepon","Heading.VoiceChatEnabled":"Chat Suara diaktifkan","Heading.VoiceChatEnabledMobile":"Chat Suara diaktifkan. Cobalah sekarang di pengalaman virtual.","Heading.VoiceChatError":"Nomor ponsel ditambahkan. Aktifkan Chat Suara di Pengaturan > Privasi > Input Mikrofon dan Kamera.","Label.ConnectWithRealLifeFriends":"Terhubung dengan teman nyata kamu via nomor ponsel (opsional).","Label.Dialog.EditPhoneCurrentNumber":"Nomor Ponsel Saat Ini:","Label.EmailInputPlaceholder":"Email kamu","Label.EmailInputPlaceholderOver13":"Email kamu","Label.EmailInputPlaceholderUnder13":"Email Orang Tua","Label.EnterCode":"Masukkan kode yang baru kami kirim ke {phoneNumber}","Label.KeepBadActorsOut":"Bantu kami menjaga keamanan di platform Roblox.","Label.No":"Tidak","Label.PasswordInputPlaceholder":"Verifikasi Password Akun","Label.PhoneNumber":"Nomor telepon","Label.RecoverIfPasswordLost":"Pulihkan akun kamu jika kamu kehilangan password.","Label.SixDigitCode":"Kode 6 digit","Label.VerifyPhoneNumber":"Verifikasi Nomor Telepon","Label.Yes":"Ya","Message.Confirmation":"Kami akan mengirim kode verifikasi via SMS ke {phoneNumber}. Biaya SMS mungkin berlaku.","Message.ConfirmationEmailNotSent":"Email konfirmasi tidak terkirim. Coba lagi nanti.","Message.InvalidEmailAddress":"Alamat email tidak valid.","Message.InvalidSmsCode":"Kode tidak valid.","Message.WrongPassword":"Password salah. Coba lagi.","Response.ErrorPhoneFormatInvalid":"Format nomor telepon ini tidak valid. Periksa dan coba lagi.","Response.ErrorTryAgain":"Terjadi kesalahan. Coba lagi nanti.","Response.InvalidPhoneNumberError":"Nomor telepon ini tidak dapat digunakan. Masukkan nomor telepon yang berbeda.","Response.PhoneHasTooManyAssociatedAccounts":"Jumlah akun yang terhubung ke satu nomor telepon sudah mencapai maksimum.","Response.PhoneNumberAlreadyLinked":"Nomor ini sudah terhubung dengan akun lain.","Response.TooManyAttemptsTryAgainLater":"Terlalu banyak percobaan. Coba lagi nanti.","Response.TooManyVerificationAttemps":"Terlalu banyak percobaan. Coba lagi dalam beberapa menit.","Response.TooManyVerificationAttempts":"Terlalu banyak percobaan. Coba lagi dalam beberapa menit."};Roblox.Lang['VerificationUpsellResources']=Roblox.Lang['Feature.VerificationUpsell'];

